-- Batch 05: independently cross-checked public building sources. Two current evidence rows per field, one audit and one evidence group.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v6';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; sub_batch int:=5; expected_before int:=84; expected_added int:=16;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v6_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($ext$[{"id":"90c8b8cc-980e-4392-ba3f-78e8676bfb4a","f":"developer","type":"text","value":"北京朝林置业有限公司","unit":"company","sources":[{"url":"https://www.bj5a-office.com/shangquan/71-2/2063.html","name":"北京写字楼租赁网","tier":"secondary"},{"url":"https://www.fffzu.com/49/","name":"北京办公选址","tier":"secondary"}],"note":"亦庄荣华中路19号朝林广场；两源同列开发公司及中央空调；停车、梯数、高度存在差异，不填"},{"id":"90c8b8cc-980e-4392-ba3f-78e8676bfb4a","f":"hvac_system","type":"text","value":"中央空调","unit":"configuration","sources":[{"url":"https://www.bj5a-office.com/shangquan/71-2/2063.html","name":"北京写字楼租赁网","tier":"secondary"},{"url":"https://www.fffzu.com/49/","name":"北京办公选址","tier":"secondary"}],"note":"亦庄荣华中路19号朝林广场；两源同列开发公司及中央空调；停车、梯数、高度存在差异，不填"},{"id":"f4bfd071-789f-4c42-b06d-afb5663fc55f","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://bj.sydc.anjuke.com/xzl-zu/7405807606/","name":"安居客商办","tier":"secondary"},{"url":"https://xiezilou123.com/index/show?catname=lzswqxzl&id=109","name":"北京凯兴世家房地产经纪有限公司","tier":"secondary"},{"url":"https://www.mjhsoho.cn/","name":"北京写字楼信息平台（仅佐证甲级定位及项目身份）","tier":"secondary"}],"note":"万柳桥西北角耕海联合中心；经纪公司与安居客均列标准层4.2m、甲级定位；97/99号门牌口径不作改写，总建面与位置一致"},{"id":"f4bfd071-789f-4c42-b06d-afb5663fc55f","f":"floor_height","type":"numeric","value":4.2,"unit":"m","sources":[{"url":"https://bj.sydc.anjuke.com/xzl-zu/7405807606/","name":"安居客商办","tier":"secondary"},{"url":"https://xiezilou123.com/index/show?catname=lzswqxzl&id=109","name":"北京凯兴世家房地产经纪有限公司","tier":"secondary"},{"url":"https://www.mjhsoho.cn/","name":"北京写字楼信息平台（仅佐证甲级定位及项目身份）","tier":"secondary"}],"note":"万柳桥西北角耕海联合中心；经纪公司与安居客均列标准层4.2m、甲级定位；97/99号门牌口径不作改写，总建面与位置一致"},{"id":"6d618f9b-c538-489a-9baf-f440e1adbde0","f":"hvac_system","type":"text","value":"中央空调","unit":"configuration","sources":[{"url":"https://www.anjigao.com/index.php/house/show/id/1131.shtml","name":"安居高","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=577&m=content","name":"北京写字楼物业租售中心2023年项目资料","tier":"secondary"}],"note":"颐和园路2号院未来科技大厦（硅谷科技大厦），公开项目资料一致支持中央空调及玻璃幕墙，不采用冲突的楼层数、面积和电梯数"},{"id":"6d618f9b-c538-489a-9baf-f440e1adbde0","f":"facade_type","type":"text","value":"玻璃幕墙","unit":"configuration","sources":[{"url":"https://www.anjigao.com/index.php/house/show/id/1131.shtml","name":"安居高","tier":"secondary"},{"url":"https://www.bjxzlwyzszx.com/index.php?a=show&c=index&catid=14&id=577&m=content","name":"北京写字楼物业租售中心2023年项目资料","tier":"secondary"}],"note":"颐和园路2号院未来科技大厦（硅谷科技大厦），公开项目资料一致支持中央空调及玻璃幕墙，不采用冲突的楼层数、面积和电梯数"},{"id":"6d618f9b-c538-489a-9baf-f440e1adbde0","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.anjigao.com/index.php/house/show/id/1131.shtml","name":"安居高","tier":"secondary"},{"url":"https://bjjingfang.com/index/lease/detail?id=10097","name":"北京京房","tier":"secondary"}],"note":"同名同址颐和园路2号；公开招商定位，非高力市场评级"},{"id":"2f1aec9e-4efe-441c-90eb-05fffb79ced7","f":"floors_below","type":"integer","value":2,"unit":"floor","sources":[{"url":"https://esf.fang.com/loupan/office/1010127119/housedetail.htm","name":"房天下楼盘资料","tier":"secondary"},{"url":"https://www.xzlsd.com/news_x.aspx?cid=44&nid=40860","name":"首都写字楼出租网2025年项目介绍","tier":"secondary"}],"note":"菜市口大街1号院2号；两渠道均明确地上17地下2，总19，与既有地上17一致；不采用冲突的电梯和面积"},{"id":"2f1aec9e-4efe-441c-90eb-05fffb79ced7","f":"building_floors","type":"integer","value":19,"unit":"floor","sources":[{"url":"https://esf.fang.com/loupan/office/1010127119/housedetail.htm","name":"房天下楼盘资料","tier":"secondary"},{"url":"https://www.xzlsd.com/news_x.aspx?cid=44&nid=40860","name":"首都写字楼出租网2025年项目介绍","tier":"secondary"}],"note":"菜市口大街1号院2号；两渠道均明确地上17地下2，总19，与既有地上17一致；不采用冲突的电梯和面积"},{"id":"04533c67-3d91-435f-b0f2-6628913bfbbd","f":"facade_type","type":"text","value":"纯铝板幕墙与中空隔音玻璃窗","unit":"configuration","sources":[{"url":"https://www.bj-sydc.com/dasha/1263.html","name":"北京商业地产楼宇信息","tier":"secondary"},{"url":"https://www.xzlsd.com/m/rentfy_x.aspx?fyId=82923&proId=3821","name":"首都写字楼出租网","tier":"secondary"}],"note":"同址原大地科技大厦，两源描述纯铝板及中空隔音玻璃；不使用相互冲突的车位数"},{"id":"04533c67-3d91-435f-b0f2-6628913bfbbd","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.bangongwang.cn/building/11853.html","name":"办公网","tier":"secondary"},{"url":"https://www.xxzf.com/fy/xxfy_6513","name":"猩猩找房","tier":"secondary"}],"note":"北四环西路67号，公开招商均列甲级定位；非市场等级"},{"id":"e90b141e-c4d5-40d3-ad77-4019c5e08a82","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://bj.58.com/xieziloupan/pan2028578390515968/","name":"58同城商办","tier":"secondary"},{"url":"https://www.huaruncazx.cn/","name":"北京写字楼信息网","tier":"secondary"}],"note":"建国路35号华润时代中心公开招商甲级定位"},{"id":"e90b141e-c4d5-40d3-ad77-4019c5e08a82","f":"developer","type":"text","value":"华润置地","unit":"company_brand","sources":[{"url":"https://www.yjzsjs.com/index/shows?catid=15&id=98","name":"项目设计相关企业项目案例","tier":"authoritative_secondary"},{"url":"https://bj.58.com/xieziloupan/pan2028578390515968/","name":"58同城商办","tier":"secondary"}],"note":"原华润饭店城市更新项目，两个来源明确开发品牌华润置地；不推断具体法人或产权主体"},{"id":"b29e1d67-d0c6-449d-8286-59636272c982","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.ecre.com.cn/buildings/2126.html","name":"易商地产楼宇资料","tier":"secondary"},{"url":"https://bjjingfang.com/index/lease/detail?id=3547","name":"北京京房","tier":"secondary"}],"note":"北苑路58号航空科技大厦的公开招商甲级定位，不写入市场分类"},{"id":"03f94714-fd1a-429f-abba-21c931f41026","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.kuntaiguojidasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.fffzu.com/213/","name":"北京办公选址","tier":"secondary"}],"note":"朝阳门外大街乙12号，两源共同支持招商甲级定位；不采用冲突的停车、面积及楼层数"},{"id":"1669ffe8-f07c-44da-882b-b359b18fa155","f":"developer","type":"text","value":"北京华建房地产有限公司","unit":"company","sources":[{"url":"https://k.sina.com.cn/article_2664057621_9eca4b15020010mc2.html","name":"房天下2023年8月报告（新浪转载）","tier":"secondary"},{"url":"https://www.bj5a-office.com/shangquan/61/127.html","name":"北京写字楼租赁网","tier":"secondary"}],"note":"东环广场东中街9/19号同一项目；两渠道分别列北京华建房地产有限公司、华建房地产有限公司；不混入办公与综合体面积"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text)) SELECT b.id bid,b.name,d.id target_id,v.f field_name,v.value new_value,v.type value_type,v.unit,v.sources,v.note FROM specs v JOIN building_brochure_data d ON d.id=v.id JOIN buildings b ON b.id=d.building_id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data q WHERE q.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(distinct substring(s->>'url' from 'https?://([^/]+)')) FROM jsonb_array_elements(v.sources) s)>=2 AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=b.id AND p.target_table='building_brochure_data' AND p.field_name=v.f) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=d.id::text AND (a.details->>'field_name'=v.f OR a.new_values ? v.f)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_url,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  SELECT r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'internet',e->>'tier',e->>'name',e->>'url',now_ts,now_ts,'cross_verified',ev,'batch_ref=ai_building_field_backfill_20261125_v6_100; unit='||r.unit||'; '||r.note||'; AI-assisted',true FROM jsonb_array_elements(r.sources) e;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>jsonb_array_length(r.sources) OR changed<2 THEN RAISE EXCEPTION 'source count mismatch'; END IF;
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v6_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_kind','external_cross_verified','source_urls',r.sources,'unit',r.unit,'verification_status','cross_verified','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value)<>jsonb_array_length(r.sources) OR NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.event_id='ai_field_fill:'||ev::text AND a.new_values->r.field_name=read_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected %, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
COMMIT;